package com.school.management.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String fullName; @Email @NotBlank @Column(unique=true) private String email; @NotBlank private String password; @Enumerated(EnumType.STRING) private Role role=Role.STUDENT; public User(){} public User(String n,String e,String p,Role r){fullName=n;email=e;password=p;role=r;} public Long getId(){return id;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public enum Role{ADMIN,TEACHER,STUDENT,PARENT,ACCOUNTANT} }
